Record Product
  Define name As String;
  Define price, stock As Integer;
EndRecord

Function amount <- Amount(price As Integer, quantity As Integer)
  Define amount As Integer;
  amount <- price * quantity;
EndFunction

Function discounted <- WithDiscount(total As Integer)
  Define discounted As Integer;
  discounted <- total - total Div 10;
EndFunction

Function valid <- ValidCode(codigo As Integer)
  Define valid As Boolean;
  valid <- codigo >= 1 And codigo <= 5;
EndFunction

Function text <- InventoryJson(products As Vector<Product>)
  Define text As String <- "{";
  For Each product In products Do
    If text <> "{" Then
      text <- text + ", ";
    EndIf
    text <- text + '"' + product.name + '": ' + toText(product.stock);
  EndFor
  text <- text + "}";
EndFunction

Subroutine Catalog() As Vector<Product>
  Define products As Vector<Product> <- vector();
  products.append(Product("Juice", 3, 10));
  products.append(Product("Sandwich", 5, 5));
  products.append(Product("Biscuit", 2, 8));
  products.append(Product("Water", 1, 12));
  products.append(Product("Fruit", 2, 6));
  Return products;
EndSubroutine

Function stock <- SavedStock(inventory As JsonValue, product As Product)
  Define stock As Integer <- product.stock;
  Switch inventory.field(product.name) Do
    Some(valor):
      Switch valor.asInteger() Do
        Some(saved): stock <- saved;
        None: stock <- product.stock;
      EndSwitch
    None: stock <- product.stock;
  EndSwitch
EndFunction

Function loaded <- ApplyInventory(products As Vector<Product>, inventory As JsonValue)
  Define loaded As Vector<Product> <- vector();
  For Each product In products Do
    loaded.append(Product(product.name, product.price, SavedStock(inventory, product)));
  EndFor
EndFunction

Subroutine LoadInventory() As Result<String, IoError>
  Define folder As DirCap <- Propagate requestDirectory(".");
  Define file As FileCap <- Propagate folder.open("inventory.json", "lectura");
  Defer
    Discard file.close();
  EndDefer
  Return file.readText();
EndSubroutine

Subroutine SaveInventory(text As String) As Result<Integer, IoError>
  Define folder As DirCap <- Propagate requestDirectory(".");
  Define file As FileCap <- Propagate folder.open("inventory.json", "escritura");
  Defer
    Discard file.close();
  EndDefer
  Return file.writeText(text);
EndSubroutine

Algorithm Kiosk
  Define products As Vector<Product> <- Catalog();
  Switch LoadInventory() Do
    Success(text):
      Switch parseJson(text) Do
        Success(inventory):
          products <- ApplyInventory(products, inventory);
          Write "Inventory loaded";
        Failure(broken): Write "Broken inventory at column ", broken.jsonColumn, ": initial stock";
      EndSwitch
    Failure(report): Write "No saved inventory (", report.code, "): initial stock";
  EndSwitch
  Define total As Integer <- 0;
  Define codigo, quantity As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read quantity;
    If Not ValidCode(codigo) Then
      Write "Code ", codigo, " does not exist";
    Else
      If quantity < 1 Then
        Write "Quantity ", quantity, " is not valid";
      Else
        Define product As Product <- products[codigo - 1];
        If quantity > product.stock Then
          Write product.name, " x ", quantity, " rejected: remaining ", product.stock;
        Else
          product.stock <- product.stock - quantity;
          products[codigo - 1] <- product;
          Write product.name, " x ", quantity, " = ", Amount(product.price, quantity);
          total <- total + Amount(product.price, quantity);
        EndIf
      EndIf
    EndIf
    Read codigo;
  EndWhile
  Write "Total: ", total;
  Write "With discount: ", WithDiscount(total);
  Switch SaveInventory(InventoryJson(products)) Do
    Success(bytes): Write "Inventory saved: ", bytes, " bytes";
    Failure(report): Write "Could not save: ", report.code;
  EndSwitch
EndAlgorithm

